/**
 * Persistent, shared rate limiting - injection 08 B.2.
 *
 * "An in-memory rate limiter is the default an agent reaches for and it is worthless
 * here: it resets on deploy, and it counts per-process."
 *
 * Both halves of that matter and they fail differently. A counter that resets on
 * deploy hands an attacker a clean slate on every release. A counter that is
 * per-process silently multiplies every limit by the instance count the moment the
 * service scales past one - and nothing fails, the bill just goes up.
 *
 * STORE: POSTGRES (AD-017). It is already running, already backed up, already in the
 * threat model, and at OTP volumes it is nowhere near being the bottleneck. Redis
 * would be faster and would be a second thing to run, pay for, secure and monitor.
 *
 * SLIDING WINDOW, NOT FIXED. A fixed window resets on a boundary and lets through
 * twice the limit across it. For the per-number-per-DAY cap - the one protecting the
 * SMS bill - that is double the money at every midnight. One row per attempt and a
 * count over the trailing window is exact, and at these volumes the row count is
 * trivial.
 *
 * NO PERSONAL DATA EVER REACHES THE TABLE. `bucket` is an HMAC of the identifier under
 * a server secret. Rate limiting happens BEFORE authentication, so a plain-text table
 * would become a list of every phone number that ever tried to sign in - a DPDP
 * liability living in the one table designed to be written by anonymous callers. The
 * limiter only ever needs equality, so a keyed hash costs it nothing. The key is a
 * secret, not a salt: a bare SHA-256 of a ten-digit Indian mobile number is
 * brute-forceable in seconds.
 */
import { createHmac } from 'node:crypto';
import { ALL_OTP_RULES, PRUNE_HORIZON_SECONDS, type RateRule } from './limits.ts';

export interface RateDecision {
  readonly allowed: boolean;
  /** Which rule rejected it. Undefined when allowed. */
  readonly rule?: string;
  /** How many more are permitted in the current window, after this call. */
  readonly remaining: number;
  /**
   * Seconds until the caller may retry. Always finite and always eventually zero -
   * B.3: "Lockout is a TIMED window that expires on its own. No state a shopkeeper
   * cannot escape without support."
   */
  readonly retryAfterSeconds: number;
  /**
   * Set only by telemetry-only rules (`lockoutSeconds: 0`): the window is over its
   * nominal max, and that is worth ALERTING on, never blocking on. See R-007.
   */
  readonly saturated?: boolean;
}

/** The only two statements a limiter needs, so tests are not coupled to a driver. */
export interface SqlRunner {
  query(sql: string, params: readonly unknown[]): Promise<{ rows: Record<string, unknown>[] }>;
}

export interface RateLimiterOptions {
  /** HMAC key. Must be a real secret in production; see `assertUsableSecret`. */
  readonly secret: string;
  /** Injected so tests can drive the window without sleeping. */
  readonly now?: () => Date;
}

/**
 * A secret that is empty or trivially short disables the privacy property without
 * disabling the limiter - so nothing fails, and the phone numbers become recoverable.
 * Refuse at construction instead of discovering it in a breach.
 */
export function assertUsableSecret(secret: string): void {
  if (typeof secret !== 'string' || secret.length < 16) {
    throw new Error(
      'rate-limit: the bucket HMAC key must be at least 16 characters. A short or ' +
        'empty key makes the hashed identifiers brute-forceable, which turns this ' +
        'table into a list of every phone number that tried to sign in.',
    );
  }
}

export class RateLimiter {
  readonly #sql: SqlRunner;
  readonly #secret: string;
  readonly #now: () => Date;

  constructor(sql: SqlRunner, opts: RateLimiterOptions) {
    assertUsableSecret(opts.secret);
    this.#sql = sql;
    this.#secret = opts.secret;
    this.#now = opts.now ?? (() => new Date());
  }

  /** Keyed, so a stored bucket reveals nothing about the identifier. */
  bucket(rule: RateRule, identifier: string): string {
    return createHmac('sha256', this.#secret)
      .update(`${rule.name}�${identifier}`)
      .digest('hex');
  }

  /**
   * Count what is already in the window WITHOUT recording anything.
   *
   * Used where a rejection must not itself consume budget - otherwise an attacker who
   * is already blocked keeps the victim blocked by continuing to hammer.
   */
  async peek(rule: RateRule, identifier: string): Promise<number> {
    const since = new Date(this.#now().getTime() - rule.windowSeconds * 1000);
    const res = await this.#sql.query(
      'SELECT count(*)::int AS n FROM rate_events WHERE bucket = $1 AND at > $2',
      [this.bucket(rule, identifier), since.toISOString()],
    );
    return Number(res.rows[0]?.n ?? 0);
  }

  /**
   * Record an attempt and decide.
   *
   * THREE STATES, because SECURITY-AUDIT TB6 has a "Lockout" column and a lockout is
   * not the same thing as a full window. 3 sends in 15 minutes earns an HOUR off, not
   * another 15 minutes - so the breach has to be remembered after the events that
   * caused it have aged out of the window.
   *
   *   1. A live lockout  -> blocked, and NOTHING is written.
   *   2. Window full     -> blocked, and exactly ONE lockout marker is written.
   *   3. Otherwise       -> allowed, one event written.
   *
   * State 1 writing nothing is what makes the lockout expire on its own. If hammering
   * while blocked extended the block, a shopkeeper whose phone retries in the
   * background could never get back in without support - and per T1.3 that is a worse
   * outcome than any threat in the table.
   */
  async consume(rule: RateRule, identifier: string): Promise<RateDecision> {
    const bucket = this.bucket(rule, identifier);
    const lockBucket = `${bucket}:lock`;
    const now = this.#now();

    /**
     * TELEMETRY-ONLY RULES NEVER DENY (R-007). `lockoutSeconds: 0` marks a rule that
     * exists to be COUNTED, not enforced - the per-IP backstop, where carrier-grade
     * NAT means one address can be a whole town of real shopkeepers. Structural
     * rather than a convention: a future caller cannot accidentally gate on it,
     * because this method will not return `allowed: false` for such a rule.
     */
    if (rule.lockoutSeconds === 0) {
      await this.#sql.query('INSERT INTO rate_events (bucket, at) VALUES ($1, $2)', [
        bucket,
        now.toISOString(),
      ]);
      const since = new Date(now.getTime() - rule.windowSeconds * 1000);
      const seen = await this.#sql.query(
        'SELECT count(*)::int AS n FROM rate_events WHERE bucket = $1 AND at > $2',
        [bucket, since.toISOString()],
      );
      const used = Number(seen.rows[0]?.n ?? 0);
      return {
        allowed: true,
        remaining: Math.max(0, rule.max - used),
        retryAfterSeconds: 0,
        saturated: used > rule.max,
      };
    }

    // --- 1 · already locked out? ---
    const lockSince = new Date(now.getTime() - rule.lockoutSeconds * 1000);
    const lock = await this.#sql.query(
      'SELECT max(at) AS newest FROM rate_events WHERE bucket = $1 AND at > $2',
      [lockBucket, lockSince.toISOString()],
    );
    const lockedAtRaw = lock.rows[0]?.newest;
    if (lockedAtRaw) {
      const endsAt = new Date(lockedAtRaw as string).getTime() + rule.lockoutSeconds * 1000;
      return {
        allowed: false,
        rule: rule.name,
        remaining: 0,
        retryAfterSeconds: Math.max(1, Math.ceil((endsAt - now.getTime()) / 1000)),
      };
    }

    // --- 2 · is the window full? ---
    const since = new Date(now.getTime() - rule.windowSeconds * 1000);
    const res = await this.#sql.query(
      'SELECT count(*)::int AS n FROM rate_events WHERE bucket = $1 AND at > $2',
      [bucket, since.toISOString()],
    );
    const used = Number(res.rows[0]?.n ?? 0);

    if (used >= rule.max) {
      // First breach: start the clock ONCE. Subsequent attempts hit branch 1 and
      // write nothing, so the release time never moves.
      await this.#sql.query('INSERT INTO rate_events (bucket, at) VALUES ($1, $2)', [
        lockBucket,
        now.toISOString(),
      ]);
      return {
        allowed: false,
        rule: rule.name,
        remaining: 0,
        retryAfterSeconds: rule.lockoutSeconds,
      };
    }

    // --- 3 · allowed ---
    await this.#sql.query('INSERT INTO rate_events (bucket, at) VALUES ($1, $2)', [
      bucket,
      now.toISOString(),
    ]);
    return { allowed: true, remaining: rule.max - used - 1, retryAfterSeconds: 0 };
  }

  /**
   * Apply several rules, stopping at the first rejection.
   *
   * Order is the caller's: put the cheapest and broadest first, so a flood is rejected
   * before the narrower rules do any work.
   *
   * Rules already consumed are NOT rolled back on a later rejection. Deliberate - an
   * attempt that reached us happened, and un-counting it would let a caller who trips
   * a late rule replay the earlier ones for free.
   */
  async consumeAll(checks: readonly { rule: RateRule; identifier: string }[]): Promise<RateDecision> {
    let tightest: RateDecision = {
      allowed: true,
      remaining: Number.MAX_SAFE_INTEGER,
      retryAfterSeconds: 0,
    };
    for (const { rule, identifier } of checks) {
      const d = await this.consume(rule, identifier);
      if (!d.allowed) return d;
      if (d.remaining < tightest.remaining) tightest = d;
    }
    return tightest;
  }

  /**
   * Delete rows that can no longer affect any decision.
   *
   * The horizon is derived from the longest rule, so adding a longer window extends it
   * automatically rather than silently pruning rows the new rule still needs.
   */
  async prune(): Promise<number> {
    const cutoff = new Date(this.#now().getTime() - PRUNE_HORIZON_SECONDS * 1000);
    const res = await this.#sql.query('DELETE FROM rate_events WHERE at < $1 RETURNING id', [
      cutoff.toISOString(),
    ]);
    return res.rows.length;
  }
}

/** Re-exported for the SECURITY-AUDIT table and operational dashboards. */
export { ALL_OTP_RULES };

