/**
 * THE AUDITED MONEY HELPERS. This is the only file in the engine permitted to perform
 * arithmetic on a money identifier; the `swafto/no-money-float` lint rule (ADR-003)
 * bans `+ - * /` on anything matching /amount|paise|total|balance|cash|sum/ everywhere
 * else.
 *
 * Money is an INTEGER NUMBER OF PAISE. Never a float, never a string, never rupees.
 * Number.MAX_SAFE_INTEGER is 9,007,199,254,740,991 paise - about INR 90 trillion - so
 * every integer we will ever hold is exact, and exact integer +/- is exact.
 *
 * Formatting to "1,234.50" happens ONLY at the render boundary, never in a calculation.
 */

/** An integer number of paise. 100 paise = 1 rupee. */
export type Paise = number;

/**
 * Thrown when a value that must be money is not a safe integer.
 *
 * A FACTORY, not `class MoneyError extends Error`, for two reasons:
 *
 *  1. The engine must parse under Hermes. The Hermes build used for the
 *     cross-runtime vector check has no `class` support at all, and the engine is
 *     the one package that has to run unmodified on both runtimes (ADR-012).
 *  2. Subclassing Error is fragile under downleveling anyway - the prototype chain
 *     is lost and `instanceof` silently stops working, which is a worse failure than
 *     not having the subclass.
 *
 * The thrown value is a real Error with `.name === 'MoneyError'`, so catching,
 * `.message` and matching on the name all behave as expected.
 */
export function MoneyError(message: string): Error {
  const err = new Error(message);
  err.name = 'MoneyError';
  return err;
}

/** Assert a value really is an integer number of paise. Cheap, and it has caught things. */
export function assertPaise(value: unknown, what = 'amount'): Paise {
  if (typeof value !== 'number' || !Number.isInteger(value) || !Number.isSafeInteger(value)) {
    throw MoneyError(
      `${what} must be a safe integer number of paise, got ${String(value)} (${typeof value}). ` +
        `Money is integer paise everywhere - see ADR-003.`,
    );
  }
  return value;
}

/** Exact addition. */
export function add(...values: Paise[]): Paise {
  let acc = 0;
  for (const v of values) acc += assertPaise(v);
  return assertPaise(acc, 'sum');
}

/** Exact subtraction, left to right. May be negative - a difference legitimately is. */
export function subtract(from: Paise, ...values: Paise[]): Paise {
  let acc = assertPaise(from);
  for (const v of values) acc -= assertPaise(v);
  return assertPaise(acc, 'difference');
}

export function sum(values: readonly Paise[]): Paise {
  let acc = 0;
  for (const v of values) acc += assertPaise(v);
  return assertPaise(acc, 'sum');
}

/* ------------------------------------------------------------------ *
 * Division. Everything below states its rounding mode (ADR-003).
 * ------------------------------------------------------------------ */

/**
 * A ratio of two money quantities. NOT money itself - a proportion.
 *
 * The numerator and denominator are kept EXACT so the caller can render the working
 * and re-derive at any precision. `basisPoints` is the rounded convenience value.
 *
 * `basisPoints` is `null` when the denominator is zero. It is never Infinity and never
 * NaN: a shop with no sales has an UNDEFINED expense ratio, not an infinite one, and
 * the UI must say "no sales yet" rather than render a symbol.
 */
export interface Ratio {
  readonly numeratorPaise: Paise;
  readonly denominatorPaise: Paise;
  /** Rounded to 1/10000. Rounding mode: HALF_UP on the absolute value. */
  readonly basisPoints: number | null;
}

/**
 * Round half away from zero ("HALF_UP" on the absolute value).
 *
 * Deliberately NOT `Math.round`, which rounds -0.5 to -0 (i.e. toward +Infinity) and
 * would make a negative ratio round differently from its positive twin. For a figure a
 * shopkeeper compares against last week, that asymmetry is a real defect.
 */
export function roundHalfAwayFromZero(x: number): number {
  return x < 0 ? -Math.round(-x) : Math.round(x);
}

/** Exact ratio, with an explicitly-rounded basis-point convenience value. */
export function ratio(numeratorPaise: Paise, denominatorPaise: Paise): Ratio {
  assertPaise(numeratorPaise, 'ratio numerator');
  assertPaise(denominatorPaise, 'ratio denominator');
  const basisPoints =
    denominatorPaise === 0
      ? null
      : roundHalfAwayFromZero((numeratorPaise * 10000) / denominatorPaise);
  return { numeratorPaise, denominatorPaise, basisPoints };
}

/**
 * Divide money into a money result. ROUNDING MODE MUST BE NAMED AT THE CALL SITE -
 * there is no default, on purpose.
 */
export function divideMoney(
  amount: Paise,
  divisor: number,
  rounding: 'half-away-from-zero' | 'floor' | 'ceil',
): Paise {
  assertPaise(amount);
  if (!Number.isFinite(divisor) || divisor === 0) {
    throw MoneyError(`divideMoney: divisor must be a non-zero finite number, got ${divisor}`);
  }
  const raw = amount / divisor;
  const out =
    rounding === 'floor'
      ? Math.floor(raw)
      : rounding === 'ceil'
        ? Math.ceil(raw)
        : roundHalfAwayFromZero(raw);
  return assertPaise(out, 'divided amount');
}

/**
 * Arithmetic mean of money. Rounding mode is explicit. Empty input is null, not 0 -
 * "no data" and "zero rupees" are different statements, and conflating them is how a
 * gated metric ends up rendering a confident zero.
 */
export function meanMoney(
  values: readonly Paise[],
  rounding: 'half-away-from-zero' | 'floor' | 'ceil' = 'half-away-from-zero',
): Paise | null {
  if (values.length === 0) return null;
  return divideMoney(sum(values), values.length, rounding);
}

/**
 * Median of money. For an even count the two middle values are averaged, rounded
 * half-away-from-zero. Empty input is null.
 *
 * Median rather than mean is used by OP5 because one unusually large day should not
 * move the baseline a shopkeeper is judged against.
 */
export function medianMoney(values: readonly Paise[]): Paise | null {
  if (values.length === 0) return null;
  const s = [...values].map((v) => assertPaise(v)).sort((a, b) => a - b);
  const mid = s.length >> 1;
  if (s.length % 2 === 1) return s[mid]!;
  return divideMoney(add(s[mid - 1]!, s[mid]!), 2, 'half-away-from-zero');
}

/**
 * Population standard deviation, in paise, rounded half-away-from-zero.
 * Used by BI2 (coefficient of variation) and BI3 (cash-flow stability).
 *
 * Population rather than sample: we are describing the days this shop actually had,
 * not inferring about a wider population of days.
 */
export function stdevMoney(values: readonly Paise[]): Paise | null {
  if (values.length === 0) return null;
  if (values.length === 1) return 0;
  const mean = sum(values) / values.length; // intentionally float, internal only
  let acc = 0;
  for (const v of values) {
    const d = v - mean;
    acc += d * d;
  }
  return assertPaise(roundHalfAwayFromZero(Math.sqrt(acc / values.length)), 'stdev');
}

/* ------------------------------------------------------------------ *
 * The render boundary
 * ------------------------------------------------------------------ */

/**
 * THE ONLY place paise become a human-readable string. Called from the view layer,
 * never from a calculation.
 *
 * LATIN NUMERALS ALWAYS, IN EVERY LANGUAGE (build prompt constraint 8). Words
 * localise; money does not. Grouping is the Indian system - 1,23,456.78 - because that
 * is how the number is read aloud in Odia, Hindi and Indian English alike.
 *
 * Deliberately hand-rolled rather than Intl.NumberFormat: the engine must behave
 * identically under Node and Hermes, and Hermes ships without full ICU by default.
 * A figure that renders differently on the phone than on the server is the exact bug
 * ADR-012's dual-runtime vectors exist to catch.
 */
export function formatPaise(
  amount: Paise,
  opts: { withSymbol?: boolean; withSign?: boolean } = {},
): string {
  assertPaise(amount);
  const negative = amount < 0;
  const abs = Math.abs(amount);
  const rupees = Math.floor(abs / 100);
  const fraction = abs % 100;

  const digits = String(rupees);
  let grouped: string;
  if (digits.length <= 3) {
    grouped = digits;
  } else {
    const last3 = digits.slice(-3);
    let rest = digits.slice(0, -3);
    const parts: string[] = [];
    while (rest.length > 2) {
      parts.unshift(rest.slice(-2));
      rest = rest.slice(0, -2);
    }
    if (rest.length) parts.unshift(rest);
    grouped = `${parts.join(',')},${last3}`;
  }

  const body = `${grouped}.${fraction < 10 ? '0' : ''}${fraction}`;
  const sign = negative ? '-' : opts.withSign ? '+' : '';
  const symbol = opts.withSymbol === false ? '' : '₹';
  return `${sign}${symbol}${body}`;
}

packages/formula-engine/src/types.ts.source:
/**
 * Domain types for the Formula Engine.
 *
 * PURE. No I/O, no clock, no locale, no network, no randomness (ADR-012).
 * Time and timezone are PASSED IN, never read. If you find yourself importing
 * anything outside this package, stop.
 *
 * The enums below duplicate those in @swafto/schema deliberately: the engine must have
 * ZERO dependencies so it runs identically under Node and Hermes (ADR-010). A test
 * asserts the two lists stay in lockstep.
 */

import type { Paise, Ratio } from './money.ts';

/* ------------------------------------------------------------------ *
 * Vocabulary
 * ------------------------------------------------------------------ */

export const SECTIONS = [
  'cash_sales',
  'upi_sales',
  'udhar_sales',
  'expense',
  'purchase',
  'udhar_collection',
  'party_payment',
  'withdrawal',
] as const;
export type Section = (typeof SECTIONS)[number];

export const MODES = ['cash', 'upi', 'other', 'udhar', 'shop_stock'] as const;
export type Mode = (typeof MODES)[number];

export const DAY_STATES = ['not_started', 'open', 'ready', 'closed', 'not_closed'] as const;
export type DayState = (typeof DAY_STATES)[number];

/** An ISO calendar date, 'YYYY-MM-DD'. Client-assigned; never rewritten (ADR-004). */
// IsoDate is defined in dates.ts and re-exported here so this module stays the one
// place a reader looks for the domain types. Declaring it twice made `export *` from
// both ambiguous (TS2308) - invisible until typechecking was switched on.
import type { IsoDate } from './dates.ts';
export type { IsoDate };

/* ------------------------------------------------------------------ *
 * IN1-IN7 - the things a shopkeeper types
 * ------------------------------------------------------------------ */

/**
 * One immutable ledger entry. Covers IN1-IN6; IN7 (the counted cash) lives on the
 * day record because it is a property of the day, not a transaction.
 */
export interface Entry {
  readonly id: string;
  readonly dayId: IsoDate;
  readonly section: Section;
  /** INTEGER PAISE. Always non-negative - sign is carried by the section. */
  readonly amount: Paise;
  readonly mode: Mode;
  readonly partyId?: string;
  /** Only meaningful on an udhar-mode purchase (D4). */
  readonly dueDate?: IsoDate;
  readonly label?: string;
  /**
   * D7: a correction is a dated adjustment posted on TODAY that REFERENCES the closed
   * day it corrects. It changes today's figures and leaves that day byte-identical.
   */
  readonly correctsDayId?: IsoDate;
  readonly createdAt: string;
  readonly source: 'manual' | 'imported';
}

/** IN7 plus the day's lifecycle. No totals - only what a human supplied. */
export interface DayRecord {
  readonly date: IsoDate;
  readonly state: DayState;
  /** Carried from yesterday's COUNTED close, never the expected figure (D6, DFD 4.7). */
  readonly openingCash: Paise | null;
  /** IN7. The cash physically counted in the box. */
  readonly countedCash: Paise | null;
  readonly differenceReason?: string;
  readonly closedAt?: string;
  /**
   * D8: sections explicitly marked "Nothing to enter". A skipped section and an
   * untouched section produce the SAME total and a DIFFERENT day state.
   */
  readonly skippedSections: readonly Section[];
}

export interface Party {
  readonly id: string;
  readonly kind: 'customer' | 'supplier';
  readonly name: string;
  readonly phone?: string;
  readonly defaultDueDays?: number;
}

/** Everything the engine needs to compute one day. Passed in; never fetched. */
export interface DayInput {
  readonly day: DayRecord;
  /** Entries whose `dayId` is this day. */
  readonly entries: readonly Entry[];
  /** P7's "prior outstanding": credit outstanding at the START of this day. */
  readonly priorCreditOutstanding: Paise;
  /** P8's "prior outstanding": supplier outstanding at the START of this day. */
  readonly priorSupplierOutstanding: Paise;
}

/* ------------------------------------------------------------------ *
 * Working - every figure must render as its derivation
 * ------------------------------------------------------------------ */

/**
 * "The expected figure is shown as its working, not as a verdict - the owner can see
 * WHICH LINE is wrong." - SWAFTO-Retail-Desk-Day-Close.pdf p.7
 *
 * Every P value carries one of these. This is not a debugging aid; it is the cash
 * check screen's primary content and the reason the product is trusted.
 */
export interface WorkingLine {
  /**
   * A stable LOCALISATION KEY the UI resolves. Never a user-facing string - the
   * engine is locale-free (ADR-012), so it cannot know what language to speak.
   */
  readonly key: string;
  readonly sign: '+' | '-';
  readonly amount: Paise;
}

export interface Working {
  readonly lines: readonly WorkingLine[];
  readonly total: Paise;
}

/** A figure plus the lines that produced it. */
export interface Figure {
  readonly value: Paise;
  readonly working: Working;
}

/* ------------------------------------------------------------------ *
 * Gating - never a spinner, never a zero, never an empty chart
 * ------------------------------------------------------------------ */

/**
 * A business-intelligence value that needs history before it means anything.
 *
 * "Every gated output states its gate in the shopkeeper's terms - 'Profit trend:
 * available after 14 closed days, 6 so far' - never a spinner, never a zero, never a
 * chart with no data in it." - build prompt
 *
 * The unavailable branch carries BOTH numbers precisely so the GateCard can say that
 * sentence without the UI having to recount anything.
 */
export type Gated<T> =
  | { readonly available: true; readonly value: T }
  | {
      readonly available: false;
      readonly requiredClosedDays: number;
      readonly closedDaysSoFar: number;
    };

export function gate<T>(
  requiredClosedDays: number,
  closedDaysSoFar: number,
  compute: () => T,
): Gated<T> {
  if (closedDaysSoFar < requiredClosedDays) {
    return { available: false, requiredClosedDays, closedDaysSoFar };
  }
  return { available: true, value: compute() };
}

/* ------------------------------------------------------------------ *
 * Output shapes
 * ------------------------------------------------------------------ */

/** P1-P8, each renderable as its working. */
export interface PrimaryOutputs {
  readonly p1TotalCashReceived: Figure;
  readonly p2TotalCashPaid: Figure;
  readonly p3ExpectedCashBalance: Figure;
  readonly p4NetSales: Figure;
  readonly p5NetPurchase: Figure;
  readonly p6TotalExpenses: Figure;
  readonly p7CreditOutstanding: Figure;
  readonly p8SupplierOutstanding: Figure;
  /**
   * Estimated profit = NET SALES - PURCHASE - EXPENSE.
   * WITHDRAWAL IS ABSENT AND THAT IS CORRECT (D3). Do not "fix" it.
   */
  readonly estimatedProfit: Figure;
}

/** OP1 - counted vs expected. Copy is a QUESTION, never a verdict. */
export interface DailyCashHealth {
  readonly expected: Paise;
  readonly counted: Paise | null;
  /** counted - expected. Negative is short, positive is extra. Null until counted. */
  readonly difference: Paise | null;
  readonly status: 'balanced' | 'short' | 'extra' | 'not_counted';
  readonly reasonRequired: boolean;
  readonly reason?: string;
}

/** OP4 / OP6 - a supplier due inside the forward horizon. */
export interface DueItem {
  readonly partyId: string;
  readonly dueDate: IsoDate;
  readonly amount: Paise;
  readonly daysUntilDue: number;
}

/**
 * OP6 - the app's single most valuable output. Must name the party, the amount, the
 * date and the shortfall, or it is not actionable.
 */
export interface CashDeficitWarning {
  readonly partyId: string;
  readonly dueDate: IsoDate;
  readonly amountDue: Paise;
  readonly projectedCash: Paise;
  /** How far short, as a positive number. */
  readonly shortfall: Paise;
}

/** Aging uses TWO VOCABULARIES, deliberately (D4, S5 p.8 AgingBadge). */
export interface AgedParty {
  readonly partyId: string;
  readonly amount: Paise;
  readonly ageDays: number;
  /**
   * 'overdue' ONLY where a due date exists; 'days_since' everywhere else.
   * "two different words, deliberately" - D4.
   */
  readonly vocabulary: 'overdue' | 'days_since' | 'current';
  readonly dueDate?: IsoDate;
}

export interface BusinessMovement {
  readonly todayNetSales: Paise;
  readonly baselineMedian: Paise | null;
  readonly direction: 'up' | 'down' | 'flat' | 'no_baseline';
  readonly ratio: Ratio;
}

export interface OperationalOutputs {
  readonly op1DailyCashHealth: DailyCashHealth;
  readonly op2ExpensePressure: Ratio;
  readonly op3CollectionEfficiency: Ratio;
  readonly op4PaymentDue: readonly DueItem[];
  readonly op5BusinessMovement: BusinessMovement;
  readonly op6CashDeficitWarnings: readonly CashDeficitWarning[];
}

/** A closed day, reduced to what the BI window needs. */
export interface ClosedDaySummary {
  readonly date: IsoDate;
  readonly netSales: Paise;
  readonly netPurchase: Paise;
  readonly totalExpenses: Paise;
  readonly profit: Paise;
  readonly countedCash: Paise;
  readonly expectedCash: Paise;
}

export interface ProfitTrend {
  readonly points: readonly { readonly date: IsoDate; readonly profit: Paise }[];
  readonly firstHalfMean: Paise;
  readonly secondHalfMean: Paise;
  readonly direction: 'up' | 'down' | 'flat';
}

export interface CashFlowStability {
  readonly stdevCountedCash: Paise;
  readonly meanCountedCash: Paise;
  readonly coefficientOfVariation: Ratio;
  /** Days whose counted cash came in short of expected. */
  readonly deficitDayCount: number;
}

export interface BusinessIntelligence {
  readonly bi1ProfitTrend: Gated<ProfitTrend>;
  readonly bi2SalesConsistency: Gated<Ratio>;
  readonly bi3CashFlowStability: Gated<CashFlowStability>;
  readonly bi4WorkingCapitalPressure: Gated<Ratio>;
  /**
   * BI5 Inventory Pressure - RESERVED, NOT IN V1 (D5). There is no item data, no
   * placeholder, and no card in Reports. "A greyed-out card is worse than no card."
   * The field exists as a reserved name only and is always `null`.
   */
  readonly bi5InventoryPressure: null;
  /**
   * BI6 · Credit Concentration - DECIDED AUTONOMOUSLY (AD-001), gate 14.
   * Item 6 of the note is cut off; chosen by the decision procedure as the
   * highest-money-cost gap in the output set. Reversal trigger recorded in
   * DECISIONS-AUTONOMOUS.md.
   */
  readonly bi6CreditConcentration: Gated<CreditConcentration>;
}

/** Everything the engine produces for one day. */
export interface DayComputation {
  readonly date: IsoDate;
  readonly state: DayState;
  readonly primary: PrimaryOutputs;
  readonly operational: OperationalOutputs;
  /** Progress ring. Opens at 1 of 10, NEVER 0 of 9 (S6 Strategy 02, S1 §05). */
  readonly progress: { readonly done: number; readonly total: number };
  /** Cash check unlocks only when all eight sections are entered or skipped (D8). */
  readonly cashCheckUnlocked: boolean;
  readonly sectionStates: Readonly<Record<Section, 'entered' | 'skipped' | 'untouched'>>;
}

/* ------------------------------------------------------------------ *
 * BI6 - Credit Concentration. Decided autonomously; see AD-001.
 * ------------------------------------------------------------------ */

/**
 * BI6 · Credit Concentration.
 *
 * "OP6 warns him about money he owes; nothing in the set warns him about money owed
 * to him being dangerously concentrated in one person."
 *
 * What share of his outstanding udhar sits with his largest customer, and with his
 * largest three - and whether that share is getting worse. A shop with INR 18,000 of
 * receivables spread over 38 customers has a collection problem; the same INR 18,000
 * with INR 11,000 owed by one man has a solvency problem, and P7 reports the same
 * number for both.
 */
export interface CreditConcentration {
  readonly totalOutstanding: Paise;
  readonly customerCount: number;
  /** The single largest debtor. Null when nothing is outstanding. */
  readonly topPartyId: string | null;
  /** Largest single customer's share of total outstanding. */
  readonly topShare: Ratio;
  /** Largest three customers' combined share. */
  readonly top3Share: Ratio;
  /**
   * Direction of the top-3 share against the baseline median of the window.
   * 'no_baseline' when there is no history to compare - never 'stable', because
   * "we cannot tell yet" and "it has not moved" are different statements.
   */
  readonly direction: 'worsening' | 'improving' | 'stable' | 'no_baseline';
  readonly baselineTop3BasisPoints: number | null;
}

packages/formula-engine/src/primary.ts.source:
/**
 * P1-P8 and estimated profit. Pure arithmetic, available from day one, NEVER gated.
 *
 * Every figure carries its WORKING - the line-by-line derivation - because the cash
 * check screen shows the expected balance "as its working, not as a verdict", so the
 * owner can see WHICH LINE is wrong rather than merely that something is.
 *
 * The two rules most likely to be "fixed" back by a well-meaning developer:
 *   D2 - only Cash mode touches the cash equation. UPI, Other, Udhar and Shop stock
 *        do NOT move cash, but all five DO count toward total expenses.
 *   D3 - withdrawal reduces cash, is NEVER an expense, and NEVER touches profit.
 * Both have named tests that fail loudly.
 */

import { add, subtract, sum, type Paise } from './money.ts';
import type {
  DayInput,
  Entry,
  Figure,
  Mode,
  PrimaryOutputs,
  Section,
  Working,
  WorkingLine,
} from './types.ts';

/* ------------------------------------------------------------------ *
 * Selectors
 * ------------------------------------------------------------------ */

const bySection = (entries: readonly Entry[], section: Section): Entry[] =>
  entries.filter((e) => e.section === section);

const totalOf = (entries: readonly Entry[]): Paise => sum(entries.map((e) => e.amount));

/** Entries in a section, restricted to one payment mode. */
const sectionModeTotal = (entries: readonly Entry[], section: Section, mode: Mode): Paise =>
  totalOf(bySection(entries, section).filter((e) => e.mode === mode));

/** Build a Figure from its lines, summing signs. Total is derived, never passed in. */
function figure(lines: readonly WorkingLine[]): Figure {
  let total = 0;
  for (const l of lines) {
    total = l.sign === '+' ? add(total, l.amount) : subtract(total, l.amount);
  }
  const working: Working = { lines, total };
  return { value: total, working };
}

/* ------------------------------------------------------------------ *
 * P1-P8
 * ------------------------------------------------------------------ */

/**
 * P1 · Total Cash Received = cash sales + cash portion of udhar collection.
 *
 * "cash_sales + cash_collections" - Day-Close doc p.9.
 * Note a collection in UPI or Other mode reduces the customer's debt (P7) but does
 * NOT put cash in the box, so it is absent here and present there.
 */
export function totalCashReceived(input: DayInput): Figure {
  const { entries } = input;
  return figure([
    { key: 'working.cash_sales', sign: '+', amount: totalOf(bySection(entries, 'cash_sales')) },
    {
      key: 'working.udhar_collected_cash',
      sign: '+',
      amount: sectionModeTotal(entries, 'udhar_collection', 'cash'),
    },
  ]);
}

/**
 * P2 · Total Cash Paid = cash purchase + cash expenses + cash party payment + withdrawal.
 *
 * D2: ONLY `cash` mode appears here. A shop-stock expense is a real cost and NOT a
 * cash outflow - if it landed here every expected balance would be wrong by that
 * amount and the shopkeeper's first reconciliation would fail for a reason he cannot
 * see.
 *
 * D3: the withdrawal IS here (it does reduce the cash in the box) and is deliberately
 * absent from P6 and from profit.
 */
export function totalCashPaid(input: DayInput): Figure {
  const { entries } = input;
  return figure([
    {
      key: 'working.cash_purchase',
      sign: '+',
      amount: sectionModeTotal(entries, 'purchase', 'cash'),
    },
    {
      key: 'working.cash_expenses',
      sign: '+',
      amount: sectionModeTotal(entries, 'expense', 'cash'),
    },
    {
      key: 'working.cash_party_payment',
      sign: '+',
      amount: sectionModeTotal(entries, 'party_payment', 'cash'),
    },
    {
      key: 'working.withdrawal_cash',
      sign: '+',
      amount: sectionModeTotal(entries, 'withdrawal', 'cash'),
    },
  ]);
}

/**
 * P3 · Expected Cash Balance = opening cash + P1 - P2.
 *
 * This is the paper sheet's formula verbatim:
 *   F = Opening Cash + Cash Sales + Udhar Cash Collection
 *       - Cash Purchase - Cash Expense - Cash Withdrawal
 *
 * The working is expanded to those seven lines rather than three, because the cash
 * check screen shows exactly those lines and the shopkeeper checks them against his
 * paper sheet one at a time.
 */
export function expectedCashBalance(input: DayInput): Figure {
  const { entries, day } = input;
  const opening = day.openingCash ?? 0;
  return figure([
    { key: 'working.opening_cash', sign: '+', amount: opening },
    { key: 'working.cash_sales', sign: '+', amount: totalOf(bySection(entries, 'cash_sales')) },
    {
      key: 'working.udhar_collected_cash',
      sign: '+',
      amount: sectionModeTotal(entries, 'udhar_collection', 'cash'),
    },
    {
      key: 'working.cash_purchase',
      sign: '-',
      amount: sectionModeTotal(entries, 'purchase', 'cash'),
    },
    {
      key: 'working.cash_expenses',
      sign: '-',
      amount: sectionModeTotal(entries, 'expense', 'cash'),
    },
    {
      key: 'working.cash_party_payment',
      sign: '-',
      amount: sectionModeTotal(entries, 'party_payment', 'cash'),
    },
    {
      key: 'working.withdrawal_cash',
      sign: '-',
      amount: sectionModeTotal(entries, 'withdrawal', 'cash'),
    },
  ]);
}

/** P4 · Net Sales = cash + UPI + udhar sales. The sheet's "TOTAL SALES (B)". */
export function netSales(input: DayInput): Figure {
  const { entries } = input;
  return figure([
    { key: 'working.cash_sales', sign: '+', amount: totalOf(bySection(entries, 'cash_sales')) },
    { key: 'working.upi_sales', sign: '+', amount: totalOf(bySection(entries, 'upi_sales')) },
    { key: 'working.udhar_sales', sign: '+', amount: totalOf(bySection(entries, 'udhar_sales')) },
  ]);
}

/** P5 · Net Purchase = all purchase, EVERY mode. The sheet's "TOTAL PURCHASE (D)". */
export function netPurchase(input: DayInput): Figure {
  return figure([
    {
      key: 'working.purchase_all_modes',
      sign: '+',
      amount: totalOf(bySection(input.entries, 'purchase')),
    },
  ]);
}

/**
 * P6 · Total Expenses = all expenses, EVERY mode including shop stock.
 *
 * D2's second half: only the cash ones appear in P2, but ALL FIVE count here and
 * toward profit. The working is broken out by mode so the shopkeeper can see why this
 * figure is larger than the cash expenses line on his cash check.
 *
 * Withdrawal is NOT here (D3).
 */
export function totalExpenses(input: DayInput): Figure {
  const { entries } = input;
  return figure([
    { key: 'working.expense_cash', sign: '+', amount: sectionModeTotal(entries, 'expense', 'cash') },
    { key: 'working.expense_upi', sign: '+', amount: sectionModeTotal(entries, 'expense', 'upi') },
    {
      key: 'working.expense_other',
      sign: '+',
      amount: sectionModeTotal(entries, 'expense', 'other'),
    },
    {
      key: 'working.expense_udhar',
      sign: '+',
      amount: sectionModeTotal(entries, 'expense', 'udhar'),
    },
    {
      key: 'working.expense_shop_stock',
      sign: '+',
      amount: sectionModeTotal(entries, 'expense', 'shop_stock'),
    },
  ]);
}

/**
 * P7 · Credit Outstanding = prior outstanding + udhar sales - udhar collections.
 *
 * Collections in ANY mode reduce the debt - a customer who settles by UPI has still
 * settled. That is why this uses the section total while P1 uses the cash-mode slice.
 */
export function creditOutstanding(input: DayInput): Figure {
  const { entries, priorCreditOutstanding } = input;
  return figure([
    { key: 'working.prior_credit_outstanding', sign: '+', amount: priorCreditOutstanding },
    { key: 'working.udhar_sales', sign: '+', amount: totalOf(bySection(entries, 'udhar_sales')) },
    {
      key: 'working.udhar_collection_all_modes',
      sign: '-',
      amount: totalOf(bySection(entries, 'udhar_collection')),
    },
  ]);
}

/**
 * P8 · Supplier Outstanding = prior + credit purchases - party payments.
 *
 * "Credit purchase" means a purchase in UDHAR mode specifically - a cash purchase
 * creates no supplier due.
 */
export function supplierOutstanding(input: DayInput): Figure {
  const { entries, priorSupplierOutstanding } = input;
  return figure([
    { key: 'working.prior_supplier_outstanding', sign: '+', amount: priorSupplierOutstanding },
    {
      key: 'working.purchase_udhar',
      sign: '+',
      amount: sectionModeTotal(entries, 'purchase', 'udhar'),
    },
    {
      key: 'working.party_payment_all_modes',
      sign: '-',
      amount: totalOf(bySection(entries, 'party_payment')),
    },
  ]);
}

/**
 * Estimated Profit = NET SALES - PURCHASE - EXPENSE.
 *
 * WITHDRAWAL IS ABSENT. That is not an omission - it is decision D3, and the sheet's
 * own formula is correct precisely because withdrawal is missing from it.
 *
 * "This is the single most common error in small-shop bookkeeping, and it is the kind
 * of thing a developer will confidently 'correct' during a refactor because it looks
 * like money going out."  - Decisions doc, D3
 *
 * If you are here to add withdrawal to this subtraction: don't. Read D3, then read the
 * vector named `d3-withdrawal-excluded-from-profit`.
 */
export function estimatedProfit(input: DayInput): Figure {
  return figure([
    { key: 'working.net_sales', sign: '+', amount: netSales(input).value },
    { key: 'working.purchase_all_modes', sign: '-', amount: netPurchase(input).value },
    { key: 'working.expenses_all_modes', sign: '-', amount: totalExpenses(input).value },
  ]);
}

export function computePrimary(input: DayInput): PrimaryOutputs {
  return {
    p1TotalCashReceived: totalCashReceived(input),
    p2TotalCashPaid: totalCashPaid(input),
    p3ExpectedCashBalance: expectedCashBalance(input),
    p4NetSales: netSales(input),
    p5NetPurchase: netPurchase(input),
    p6TotalExpenses: totalExpenses(input),
    p7CreditOutstanding: creditOutstanding(input),
    p8SupplierOutstanding: supplierOutstanding(input),
    estimatedProfit: estimatedProfit(input),
  };
}

apps/api/test/rate-limit.spec.ts.source:
/**
 * Injection 08 B.2, proven: "a test that restarts the service mid-limit and asserts
 * the counter survived."
 *
 * The restart is the whole point, so it is not simulated by clearing a variable. A
 * second `RateLimiter` is built over a SEPARATE Postgres connection - which is what a
 * redeployed process is - and the count carries. A third runs CONCURRENTLY with the
 * first, which is the other half of B.2 that an in-memory limiter also fails:
 * counting per-process.
 *
 * Time is injected, never slept. A test that sleeps for an hour to prove an hourly
 * window is a test nobody runs.
 */
import { describe, it, expect, afterAll } from 'vitest';
import { readFileSync } from 'node:fs';
import { migrationUp, migrationDown } from '../../../packages/schema/src/spec.ts';
import { RateLimiter, assertUsableSecret, type SqlRunner } from '../src/rate-limit/store.ts';
import {
  OTP_LIMITS,
  ALL_OTP_RULES,
  OTP_TTL_SECONDS,
  PRUNE_HORIZON_SECONDS,
} from '../src/rate-limit/limits.ts';

const DEFAULT_URL = 'postgres://postgres:postgres@localhost:55432/swafto_test';
const DB_URL = process.env.DATABASE_URL ?? DEFAULT_URL;
const SECRET = 'test-secret-key-at-least-16';

const PHONE = '+919000000001';
const OTHER_PHONE = '+919000000002';
const DEVICE = 'device-a';
const IP = '203.0.113.7'; // TEST-NET-3, reserved for documentation

/* ---- connect at module load, for the reason postgres.spec.ts documents ---- */
// Deliberately loose: `pg` is CommonJS with awkward ESM interop, and these tests
// exercise SQL behaviour, not driver typings. Typing it properly here would couple
// the suite to a dependency shape we do not otherwise depend on.
type PgClient = any;
const clients: PgClient[] = [];
let reachable = false;

/**
 * ITS OWN SCHEMA, and this is not tidiness.
 *
 * Vitest runs spec files in parallel workers. This suite and `postgres.spec.ts` both
 * run the migrations, and against one shared `public` schema they raced on CREATE
 * TABLE - "duplicate key value violates unique constraint pg_type_typname_nsp_index".
 * The loser caught the error, set `reachable = false`, and SKIPPED ALL THIRTEEN TESTS
 * while the run stayed green.
 *
 * That is the exact failure this file was written to stop appearing elsewhere: a
 * suite that passes when run alone and quietly does nothing in the run everyone
 * actually performs. A separate schema removes the collision without serialising the
 * suite.
 */
const SCHEMA = 'ratelimit_test';

async function connect(): Promise<PgClient> {
  const mod = (await import('pg')) as unknown as Record<string, unknown>;
  const Client = (mod.Client ?? (mod.default as Record<string, unknown>)?.Client) as
    | (new (cfg: unknown) => PgClient)
    | undefined;
  if (!Client) throw new Error('pg.Client not found on the module');
  const c = new Client({ connectionString: DB_URL, connectionTimeoutMillis: 4000 });
  await c.connect();
  await c.query(`CREATE SCHEMA IF NOT EXISTS ${SCHEMA}`);
  await c.query(`SET search_path TO ${SCHEMA}`);
  clients.push(c);
  return c;
}

let primary: PgClient;
{
  try {
    primary = await connect();
    for (const s of migrationDown('postgres')) await primary.query(s);
    for (const s of migrationUp('postgres')) await primary.query(s);
    reachable = true;
  } catch (err) {
    console.error('[B.2/rate-limit] connect failed:', (err as Error).message);
  }
}

afterAll(async () => {
  for (const c of clients) await c.end().catch(() => {});
});

const maybe = () => (reachable ? it : it.skip);

/** A clock the test drives. Real time never enters these assertions. */
function clockAt(startMs: number) {
  let t = startMs;
  return {
    now: () => new Date(t),
    advanceSeconds(s: number) {
      t += s * 1000;
    },
  };
}

const runner = (c: PgClient): SqlRunner => ({
  query: (sql, params) => c.query(sql, params as unknown[]),
});

const T0 = Date.parse('2026-09-19T08:00:00.000Z');

describe('B.2 · rate limits are persistent and shared', () => {
  it('reports whether a database was reachable', () => {
    if (!reachable) {
      console.log(
        '\n  [B.2/rate-limit] SKIPPED - no reachable database.' +
          '\n  Start one with: node tools/pg-up.mjs\n',
      );
    }
    expect(true).toBe(true);
  });

  maybe()('refuses a secret too short to protect the identifiers', () => {
    // Not cosmetic: a weak key makes the bucket column a recoverable list of every
    // phone number that tried to sign in, and NOTHING would fail at runtime.
    expect(() => assertUsableSecret('')).toThrow(/at least 16/);
    expect(() => assertUsableSecret('short')).toThrow(/at least 16/);
    expect(() => assertUsableSecret(SECRET)).not.toThrow();
  });

  maybe()('never stores the identifier, only a keyed hash of it', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });

    await limiter.consume(OTP_LIMITS.sendPerPhoneDaily, PHONE);

    const rows = await primary.query('SELECT bucket FROM rate_events', []);
    expect(rows.rows.length).toBe(1);
    const stored: string = rows.rows[0].bucket;
    expect(stored).not.toContain(PHONE);
    expect(stored).not.toContain('9000000001');
    expect(stored).toMatch(/^[0-9a-f]{64}$/);

    // The key must actually matter - a different secret gives a different bucket,
    // which is what makes the stored value unreadable to anyone without it.
    const other = new RateLimiter(runner(primary), {
      secret: 'a different test key',
      now: clock.now,
    });
    expect(other.bucket(OTP_LIMITS.sendPerPhoneDaily, PHONE)).not.toBe(
      limiter.bucket(OTP_LIMITS.sendPerPhoneDaily, PHONE),
    );
  });

  maybe()('allows exactly `max` and then rejects', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    for (let i = 0; i < rule.max; i += 1) {
      const d = await limiter.consume(rule, PHONE);
      expect(d.allowed, `attempt ${i + 1} of ${rule.max}`).toBe(true);
      expect(d.remaining).toBe(rule.max - i - 1);
    }
    const over = await limiter.consume(rule, PHONE);
    expect(over.allowed).toBe(false);
    expect(over.rule).toBe(rule.name);
    expect(over.retryAfterSeconds).toBeGreaterThan(0);
  });

  maybe()('THE B.2 TEST: the counter survives a restart', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    // --- instance 1, stopped mid-limit ---
    const before = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    for (let i = 0; i < rule.max - 1; i += 1) {
      expect((await before.consume(rule, PHONE)).allowed).toBe(true);
    }

    // --- deploy: the process goes away, connection and all ---
    const restarted = await connect();
    const after = new RateLimiter(runner(restarted), { secret: SECRET, now: clock.now });

    // One left, then blocked. An in-memory limiter would allow `max` more here, which
    // is the entire defect B.2 describes.
    expect((await after.consume(rule, PHONE)).allowed).toBe(true);
    const blocked = await after.consume(rule, PHONE);
    expect(blocked.allowed).toBe(false);
    expect(blocked.rule).toBe(rule.name);
  });

  maybe()('THE OTHER HALF: two instances share one budget', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    const second = await connect();
    const a = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const b = new RateLimiter(runner(second), { secret: SECRET, now: clock.now });

    // Alternate between them. Per-process counting would let each run to `max`.
    let allowed = 0;
    for (let i = 0; i < rule.max * 2; i += 1) {
      const d = await (i % 2 === 0 ? a : b).consume(rule, PHONE);
      if (d.allowed) allowed += 1;
    }
    expect(allowed).toBe(rule.max);
  });

  maybe()('the lockout is a TIMED window that expires on its own (B.3, T1.3)', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerPhoneBurst; // 3 / 15 min, lockout 1 h

    for (let i = 0; i < rule.max; i += 1) await limiter.consume(rule, PHONE);
    const blocked = await limiter.consume(rule, PHONE);
    expect(blocked.allowed).toBe(false);
    // The lockout column is the point: breaching a 15-minute window earns an HOUR,
    // not another 15 minutes.
    expect(blocked.retryAfterSeconds).toBe(rule.lockoutSeconds);

    // THE PROPERTY THAT MATTERS MOST HERE. Hammering while blocked must not push the
    // release further away. A phone retrying in the background would otherwise lock a
    // shopkeeper out indefinitely, and T1.3 says that is worse than any threat in the
    // table.
    clock.advanceSeconds(60);
    for (let i = 0; i < 20; i += 1) await limiter.consume(rule, PHONE);
    const still = await limiter.consume(rule, PHONE);
    expect(still.allowed).toBe(false);
    expect(still.retryAfterSeconds).toBe(rule.lockoutSeconds - 60);

    // Still locked just before the hour, even though the 15-minute window emptied
    // long ago - which is exactly what a plain sliding window would have got wrong.
    clock.advanceSeconds(rule.lockoutSeconds - 120);
    expect((await limiter.consume(rule, PHONE)).allowed).toBe(false);

    // And it clears by itself, with no support call.
    clock.advanceSeconds(120);
    expect((await limiter.consume(rule, PHONE)).allowed).toBe(true);
  });

  maybe()('a fixed window would leak double across a boundary; this one does not', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    // Spend the budget at the END of an hour...
    clock.advanceSeconds(rule.windowSeconds - 60);
    for (let i = 0; i < rule.max; i += 1) {
      expect((await limiter.consume(rule, PHONE)).allowed).toBe(true);
    }
    // ...then step just past where a FIXED window would reset. A fixed window would
    // allow `max` again immediately: 2x the SMS bill at every boundary.
    clock.advanceSeconds(120);
    expect((await limiter.consume(rule, PHONE)).allowed).toBe(false);
  });

  maybe()('limits are per identifier, so one number cannot block another', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    for (let i = 0; i < rule.max; i += 1) await limiter.consume(rule, PHONE);
    expect((await limiter.consume(rule, PHONE)).allowed).toBe(false);
    expect((await limiter.consume(rule, OTHER_PHONE)).allowed).toBe(true);
  });

  maybe()('the per-IP backstop NEVER denies, however hard it is hammered (R-007)', async () => {
    // Carrier-grade NAT means one address can be a whole town of real shopkeepers.
    // This rule exists to be COUNTED, not enforced, and that has to be structural -
    // a future caller must not be able to gate on it by accident.
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerIp;

    expect(rule.lockoutSeconds).toBe(0);

    let denied = 0;
    let saturated = false;
    for (let i = 0; i < rule.max + 25; i += 1) {
      const d = await limiter.consume(rule, IP);
      if (!d.allowed) denied += 1;
      if (d.saturated) saturated = true;
    }
    expect(denied, 'a telemetry-only rule must never deny').toBe(0);
    expect(saturated, 'but it must REPORT that it went over').toBe(true);
  }, 180_000);

  maybe()('consumeAll stops at the first rejection and names the rule', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });

    const checks = [
      { rule: OTP_LIMITS.sendPerIp, identifier: IP },
      { rule: OTP_LIMITS.sendPerDevice, identifier: DEVICE },
      { rule: OTP_LIMITS.sendPerPhoneBurst, identifier: PHONE },
      { rule: OTP_LIMITS.sendPerPhoneDaily, identifier: PHONE },
    ];

    // The tightest rule in that list is perPhonePerHour.
    for (let i = 0; i < OTP_LIMITS.sendPerPhoneBurst.max; i += 1) {
      expect((await limiter.consumeAll(checks)).allowed).toBe(true);
    }
    const d = await limiter.consumeAll(checks);
    expect(d.allowed).toBe(false);
    expect(d.rule).toBe(OTP_LIMITS.sendPerPhoneBurst.name);
  });

  maybe()('peek does not consume', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });
    const rule = OTP_LIMITS.sendPerPhoneBurst;

    await limiter.consume(rule, PHONE);
    expect(await limiter.peek(rule, PHONE)).toBe(1);
    expect(await limiter.peek(rule, PHONE)).toBe(1);
    expect(await limiter.peek(rule, PHONE)).toBe(1);
  });

  maybe()('prune removes only rows past the longest window', async () => {
    await primary.query('DELETE FROM rate_events');
    const clock = clockAt(T0);
    const limiter = new RateLimiter(runner(primary), { secret: SECRET, now: clock.now });

    await limiter.consume(OTP_LIMITS.sendPerPhoneDaily, PHONE); // will age out
    clock.advanceSeconds(PRUNE_HORIZON_SECONDS + 60);
    await limiter.consume(OTP_LIMITS.sendPerPhoneDaily, OTHER_PHONE); // fresh

    expect(await limiter.prune()).toBe(1);
    const left = await primary.query('SELECT count(*)::int AS n FROM rate_events', []);
    expect(left.rows[0].n).toBe(1);
  });

  maybe()('every rule is traceable to the SECURITY-AUDIT table', () => {
    // These numbers are the spec's, not ours. The `source` string names the row each
    // came from, so a future change has to confront the ruling rather than drift past
    // it - which is what nearly happened when this file was first written with five
    // invented limits and a paragraph of justification for each.
    expect(ALL_OTP_RULES.length).toBeGreaterThan(0);
    for (const r of ALL_OTP_RULES) {
      expect(r.max, r.name).toBeGreaterThan(0);
      expect(r.windowSeconds, r.name).toBeGreaterThan(0);
      // 0 is legal and meaningful: it marks a TELEMETRY-ONLY rule, which never
      // denies (R-007). Anything else must carry a real lockout.
      expect(r.lockoutSeconds, r.name).toBeGreaterThanOrEqual(0);
      if (r.lockoutSeconds === 0) {
        expect(r.name, 'only the per-IP backstop is telemetry-only').toBe(
          OTP_LIMITS.sendPerIp.name,
        );
      }
      expect(r.source, r.name + ' source').toMatch(/SECURITY-AUDIT TB6/);
    }
  });

  maybe()('the code table and the audit table agree', () => {
    // The executable copy must not drift from the ruling it transcribes, so the
    // numbers are read back out of SECURITY-AUDIT.md and compared.
    const md = readFileSync(new URL('../../../SECURITY-AUDIT.md', import.meta.url), 'utf8');
    // Compared as whole table rows with whitespace collapsed - simpler to read than
    // a regex, and it fails loudly if the audit table is reformatted, which is the
    // moment somebody is most likely to change a number by accident.
    const rows = md
      .split(/\r?\n/)
      .filter((l) => l.trimStart().startsWith('|'))
      .map((l) => l.replace(/\*\*/g, '').replace(/\s+/g, ' ').trim());

    expect(rows).toContain('| Per phone number - send | 3 | 15 min | 1 h |');
    expect(rows).toContain('| Per phone number - send | 10 | 24 h | 24 h |');
    expect(rows).toContain('| Per IP - send | 2000 | 1 h | none - telemetry only |');
    expect(rows).toContain('| Per device id - send | 5 | 1 h | 1 h |');
    expect(
      rows.some((r) => r.startsWith('| Per phone number - verify attempts | 5 per code |')),
    ).toBe(true);
    expect(md).toContain('10-minute TTL');

    expect(OTP_LIMITS.sendPerPhoneBurst.max).toBe(3);
    expect(OTP_LIMITS.sendPerPhoneBurst.windowSeconds).toBe(15 * 60);
    expect(OTP_LIMITS.sendPerPhoneDaily.max).toBe(10);
    expect(OTP_LIMITS.sendPerPhoneDaily.windowSeconds).toBe(24 * 3600);
    expect(OTP_LIMITS.sendPerIp.max).toBe(2000);
    expect(OTP_LIMITS.sendPerIp.lockoutSeconds).toBe(0);
    expect(OTP_LIMITS.sendPerDevice.max).toBe(5);
    expect(OTP_LIMITS.verifyPerCode.max).toBe(5);
    expect(OTP_TTL_SECONDS).toBe(10 * 60);
  });
});

packages/formula-engine/test/entry-order.source:
/**
 * ADR-017 Decision C, made executable.
 *
 * WHY THIS FILE EXISTS. Entry ids are UUIDv7, which embeds a millisecond timestamp.
 * When a device clock corrects BACKWARDS - and on a shop phone it does - ids issued
 * after the correction sort before ids issued earlier in real time. Anything ordering
 * entries by id, or by `createdAt`, interleaves them wrongly for the width of the
 * correction.
 *
 * ADR-017 tolerates that, on one stated ground: **no figure depends on entry order**.
 * Every total is a `sum`, and sums are order-independent; the ordered outputs that do
 * exist are ordered by VALUE with a deterministic tiebreaker. That ground was
 * established by reading the engine, and a property established by reading is a
 * property that a future refactor silently removes.
 *
 * So it is asserted here, over every vector: permute the entries, recompute, and the
 * entire result must be byte-identical. The day a `.find()` or an `entries[0]` creeps
 * into a figure, this fails - and ADR-017's reversal trigger, adding a monotonic local
 * sequence, becomes due BEFORE the data that would need ordering exists.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { evaluateVector, type VectorCase, type VectorFile } from '../../../tools/vector-harness.ts';

const file = JSON.parse(
  readFileSync(new URL('../vectors.json', import.meta.url), 'utf8'),
) as VectorFile;
const vectors: VectorCase[] = Array.isArray(file) ? file : file.vectors;

/**
 * Key order is irrelevant, ARRAY order is not - an ordered output whose order changed
 * with the input order is exactly the defect being hunted, so arrays are compared as
 * given.
 */
function stable(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(stable).join(',')}]`;
  if (v && typeof v === 'object') {
    const o = v as Record<string, unknown>;
    return `{${Object.keys(o)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${stable(o[k])}`)
      .join(',')}}`;
  }
  return JSON.stringify(v) ?? 'null';
}

/** Deterministic, seeded, and not the identity for any list of two or more. */
function shuffled<T>(xs: readonly T[]): T[] {
  const out = [...xs];
  let seed = 0x5bd1e995;
  for (let i = out.length - 1; i > 0; i -= 1) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const j = seed % (i + 1);
    // Both indices are in range by construction, but a destructured swap is typed as
    // T | undefined under noUncheckedIndexedAccess. An explicit temp is honest about
    // it without an assertion that would also hide a real out-of-range bug.
    const a = out[i] as T;
    const b = out[j] as T;
    out[i] = b;
    out[j] = a;
  }
  return out;
}

function withEntries(v: VectorCase, entries: unknown[]): VectorCase {
  return { ...v, input: { ...v.input, entries } } as VectorCase;
}

const entriesOf = (v: VectorCase): unknown[] =>
  ((v.input as unknown as { entries?: unknown[] }).entries ?? []) as unknown[];

describe('ADR-017 C · every figure is independent of entry order', () => {
  const withEntryLists = vectors.filter((v) =>
    Array.isArray((v.input as unknown as { entries?: unknown[] }).entries),
  );
  const permutable = withEntryLists.filter((v) => entriesOf(v).length > 1);

  it('the corpus actually contains entries to permute', () => {
    // A permutation suite over empty lists passes vacuously and proves nothing - the
    // same failure mode as assertPaise at 0/59.
    expect(withEntryLists.length).toBeGreaterThan(0);
    expect(permutable.length).toBeGreaterThan(0);
  });

  for (const v of permutable) {
    it(`${v.name}: reversed and shuffled give identical results`, () => {
      const entries = entriesOf(v);
      const base = stable(evaluateVector(v));
      expect(stable(evaluateVector(withEntries(v, [...entries].reverse())))).toBe(base);
      expect(stable(evaluateVector(withEntries(v, shuffled(entries))))).toBe(base);
    });
  }
});

packages/schema/test/rejects.spec.ts.source:
/**
 * Runs the REJECTION CORPUS (§5.11) against every layer each case names.
 *
 * §5.11.2: a rejection is tested at EVERY layer that claims to enforce it. A
 * rejection only the API performs is absent in the app; one only the app performs is
 * absent on sync.
 *
 * Cases whose only layer is `api` are reported as PENDING and counted, never skipped
 * silently - an untested rejection that looks green is precisely the failure this
 * corpus exists to prevent.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { DatabaseSync } from 'node:sqlite';
import { migrationUp } from '../src/spec.ts';
import * as engine from '../../formula-engine/src/index.ts';

interface RejectCase {
  name: string;
  violates: string;
  layers: ('engine' | 'schema' | 'api')[];
  engine?: { fn: string; args: unknown[] };
  schema?: { table: string; columns: string; values: string };
  messageMatches?: string;
}

const corpus = JSON.parse(
  readFileSync(new URL('../../formula-engine/rejects.json', import.meta.url), 'utf8'),
) as { count: number; cases: RejectCase[] };

const SHOP = '00000000-0000-7000-8000-000000000001';
const PARTY = '00000000-0000-7000-8000-0000000000c1';
const DUPE = '01890000-0000-7000-8000-000000009999';
const OPEN_DAY = '2026-07-15';
const CLOSED_DAY = '2026-07-12';
const NOW = '2026-07-15T10:00:00.000Z';

let seq = 0;

function seeded(): DatabaseSync {
  const db = new DatabaseSync(':memory:');
  db.exec('PRAGMA foreign_keys = ON');
  for (const s of migrationUp('sqlite')) db.exec(s);
  db.exec(`INSERT INTO shops (id, name, type, language, created_at)
           VALUES ('${SHOP}', 'Test Store', 'kirana', 'en', '${NOW}')`);
  db.exec(`INSERT INTO days (shop_id, date, state, opening_cash, created_at)
           VALUES ('${SHOP}', '${OPEN_DAY}', 'open', 150000, '${NOW}')`);
  db.exec(`INSERT INTO days (shop_id, date, state, opening_cash, counted_cash, closed_at, created_at)
           VALUES ('${SHOP}', '${CLOSED_DAY}', 'closed', 150000, 605000, '${NOW}', '${NOW}')`);
  db.exec(`INSERT INTO parties (id, shop_id, kind, name, created_at)
           VALUES ('${PARTY}', '${SHOP}', 'customer', 'A Customer', '${NOW}')`);
  // Pre-existing row, so the duplicate-id case has something to collide with.
  db.exec(`INSERT INTO entries (id, shop_id, day_id, section, amount, mode, created_at, source)
           VALUES ('${DUPE}', '${SHOP}', '${OPEN_DAY}', 'cash_sales', 1000, 'cash', '${NOW}', 'manual')`);
  return db;
}

const substitute = (s: string) =>
  s
    .split('{{shop}}')
    .join(SHOP)
    .split('{{party}}')
    .join(PARTY)
    .split('{{openDay}}')
    .join(OPEN_DAY)
    .split('{{closedDay}}')
    .join(CLOSED_DAY)
    .split('{{now}}')
    .join(NOW)
    .split('{{dupe}}')
    .join(DUPE)
    .split('{{uuid}}')
    .join(`01890000-0000-7000-8000-${String(++seq).padStart(12, '0')}`);

describe('§5.11 · the rejection corpus is complete and coherent', () => {
  it('every case names at least one layer and the rule it violates', () => {
    for (const c of corpus.cases) {
      expect(c.layers.length, `${c.name} names no layer`).toBeGreaterThan(0);
      expect(c.violates.length, `${c.name} does not say what it violates`).toBeGreaterThan(10);
    }
  });

  it('reports how many cases are still PENDING an unbuilt layer', () => {
    const pending = corpus.cases.filter((c) => c.layers.every((l) => l === 'api'));
    // Recorded, not hidden. These become real when G6-G8 land API validation.
    console.log(
      `\n  [5.11] ${pending.length} of ${corpus.count} cases are PENDING the API layer:\n` +
        pending.map((p) => `        - ${p.name}`).join('\n') +
        '\n',
    );
    expect(pending.length).toBeLessThan(corpus.count);
  });
});

describe('§5.11 · ENGINE layer refuses what it must', () => {
  const engineCases = corpus.cases.filter((c) => c.layers.includes('engine'));

  it('has engine cases to run', () => {
    expect(engineCases.length).toBeGreaterThan(0);
  });

  for (const c of engineCases) {
    it(`${c.name} - ${c.violates}`, () => {
      const fns = engine as unknown as Record<string, (...a: unknown[]) => unknown>;
      const fn = fns[c.engine!.fn];
      expect(fn, `engine exports no function named ${c.engine!.fn}`).toBeTypeOf('function');
      if (typeof fn !== 'function') throw new Error('unreachable: asserted above');
      let threw: Error | null = null;
      try {
        fn(...c.engine!.args);
      } catch (err) {
        threw = err as Error;
      }
      expect(threw, `${c.name} was ACCEPTED by the engine`).not.toBeNull();
      if (c.messageMatches) expect(threw!.message).toContain(c.messageMatches);
    });
  }
});

describe('§5.11 · SCHEMA layer refuses what it must', () => {
  const schemaCases = corpus.cases.filter((c) => c.layers.includes('schema'));

  it('has schema cases to run', () => {
    expect(schemaCases.length).toBeGreaterThan(0);
  });

  for (const c of schemaCases) {
    it(`${c.name} - ${c.violates}`, () => {
      const db = seeded();
      const sql = `INSERT INTO ${c.schema!.table} (${c.schema!.columns}) VALUES (${substitute(
        c.schema!.values,
      )})`;
      let threw: Error | null = null;
      try {
        db.exec(sql);
      } catch (err) {
        threw = err as Error;
      }
      expect(threw, `${c.name} was ACCEPTED by the database`).not.toBeNull();
      if (c.messageMatches) expect(threw!.message).toContain(c.messageMatches);
    });
  }
});

apps/api/test/sms-templates.spec.ts.source:
/**
 * G6 · The DLT constraint is a DESIGN constraint, not a launch task.
 *
 * These tests exist so that an unregistrable SMS is impossible to write, rather than
 * discovered weeks later when the operator rejects the registration.
 */
import { describe, it, expect, beforeEach } from 'vitest';
import {
  DLT_LIMITS,
  LANGUAGES,
  TEMPLATES,
  TEMPLATE_IDS,
  countSlots,
  isUnicode,
  renderedLength,
  segmentLimit,
} from '../src/sms/templates.ts';
import { assertSendable } from '../src/sms/port.ts';
import { StubSmsPort } from '../src/sms/stub.ts';

const CODE = '482913'; // synthetic 6-digit OTP
const PHONE = '+919999900000'; // synthetic

describe('G6 · every registered template satisfies the DLT caps', () => {
  for (const id of TEMPLATE_IDS) {
    for (const lang of LANGUAGES) {
      const body = TEMPLATES[id].text[lang];

      it(`${id}/${lang} has exactly the declared number of variable slots`, () => {
        expect(countSlots(body)).toBe(TEMPLATES[id].variableCount);
      });

      it(`${id}/${lang} is within the tightest operator variable cap`, () => {
        expect(countSlots(body)).toBeLessThanOrEqual(DLT_LIMITS.maxVariablesPerTemplate);
      });

      it(`${id}/${lang} does NOT end with a variable`, () => {
        expect(body.trimEnd().endsWith('{#var#}')).toBe(false);
      });

      it(`${id}/${lang} keeps variable content under 40% of the message`, () => {
        const messageChars = renderedLength(body, [CODE]);
        expect((CODE.length / messageChars) * 100).toBeLessThanOrEqual(
          DLT_LIMITS.maxVariableSharePercent,
        );
      });

      it(`${id}/${lang} fits ONE SMS segment (70 chars for Unicode scripts)`, () => {
        const total = renderedLength(body, [CODE]);
        const limit = segmentLimit(body);
        expect(
          total,
          `${id}/${lang} is ${total} chars against a ${limit}-char segment; it would ` +
            `cost two segments on every send, forever`,
        ).toBeLessThanOrEqual(limit);
      });

      it(`${id}/${lang} uses LATIN numerals only (constraint 8)`, () => {
        // Devanagari U+0966-096F, Odia U+0B66-0B6F. Words localise; numbers do not.
        expect(body).not.toMatch(/[०-९୦-୯]/);
      });
    }
  }

  it('carries no personal data beyond the code - one variable per template', () => {
    for (const id of TEMPLATE_IDS) {
      expect(TEMPLATES[id].variableCount, `${id} must carry only the OTP`).toBe(1);
    }
  });

  it('classifies Hindi and Odia as Unicode and English as GSM-7', () => {
    expect(isUnicode(TEMPLATES.otp_signin.text.en)).toBe(false);
    expect(isUnicode(TEMPLATES.otp_signin.text.hi)).toBe(true);
    expect(isUnicode(TEMPLATES.otp_signin.text.od)).toBe(true);
    expect(segmentLimit(TEMPLATES.otp_signin.text.od)).toBe(70);
    expect(segmentLimit(TEMPLATES.otp_signin.text.en)).toBe(160);
  });

  it('warns the user never to share the code, in every language', () => {
    // OTP-relay fraud works by asking the victim to read the code out loud. The
    // warning is the only defence at the moment it matters.
    for (const id of TEMPLATE_IDS) {
      expect(TEMPLATES[id].text.en.toLowerCase()).toContain('never share');
      expect(TEMPLATES[id].text.hi).toMatch(/बताएं|बताए/);
      expect(TEMPLATES[id].text.od).toMatch(/କୁହନ୍ତୁ/);
    }
  });

  it('uses a DISTINCT template per purpose, so an unexpected code is noticeable', () => {
    // A generic "your code is X" would register faster and tell a victim nothing.
    const en = TEMPLATE_IDS.map((id) => TEMPLATES[id].text.en);
    expect(new Set(en).size).toBe(TEMPLATE_IDS.length);
  });
});

describe('G6 · an unregistrable message cannot be sent by ANY route', () => {
  let sms: StubSmsPort;
  beforeEach(() => {
    sms = new StubSmsPort();
  });

  const good = {
    phone: PHONE,
    templateId: 'otp_signin' as const,
    variables: [CODE],
    languageTag: 'en' as const,
  };

  it('accepts a well-formed send', async () => {
    await expect(sms.send(good)).resolves.toBeUndefined();
    expect(sms.count()).toBe(1);
    expect(sms.last()?.variables).toEqual([CODE]);
  });

  it('REJECTS an unregistered templateId', () => {
    expect(() => assertSendable({ ...good, templateId: 'otp_marketing_blast' as never })).toThrow(
      /Unregistered templateId/,
    );
  });

  it('REJECTS a variable-count mismatch, in both directions', () => {
    expect(() => assertSendable({ ...good, variables: [CODE, 'extra'] })).toThrow(/variable slot/);
    expect(() => assertSendable({ ...good, variables: [] })).toThrow(/variable slot/);
  });

  it('REJECTS a variable longer than the 30-character DLT cap', () => {
    expect(() => assertSendable({ ...good, variables: ['x'.repeat(31)] })).toThrow(
      /caps it at 30/,
    );
  });

  it('REJECTS an oversized variable against a short Unicode body', () => {
    // 30 chars of variable against the compact Odia body breaches the share cap or
    // the 70-char segment - either way it must not send.
    expect(() =>
      assertSendable({ ...good, languageTag: 'od', variables: ['9'.repeat(30)] }),
    ).toThrow();
  });

  it('has NO free-text path: an SmsRequest carries no message field', () => {
    // A string body would be unregistrable at the operator, and a free-text path in
    // development is how a free-text call site reaches production.
    const keys = Object.keys(good).sort();
    expect(keys).toEqual(['languageTag', 'phone', 'templateId', 'variables']);
    for (const banned of ['message', 'body', 'text', 'content']) {
      expect(keys).not.toContain(banned);
    }
  });

  it('propagates a carrier failure rather than swallowing it', async () => {
    sms.failNext = true;
    await expect(sms.send(good)).rejects.toThrow(/carrier failure/);
    expect(sms.count()).toBe(0);
  });

  it('sends in the language the shopkeeper chose', async () => {
    await sms.send({ ...good, languageTag: 'od' });
    expect(sms.last()?.languageTag).toBe('od');
  });
});

packages/formula-engine/test/vectors.spe.source:
/**
 * The golden vectors, executed INSIDE the test runner.
 *
 * WHY THIS EXISTS, AND WHY IT IS A §5.12 FINDING RATHER THAN A CONVENIENCE.
 *
 * The 63 vectors are the engine's primary evidence, and until now they ran only in
 * `tools/run-vectors.mjs` - a separate Node process. Two consequences, neither
 * obvious:
 *
 *   1. `npx vitest run` said "231 passed" while exercising almost none of the
 *      engine's behaviour. Anyone reading that number would draw the wrong
 *      conclusion about what had just been checked.
 *   2. B3 demands 100% BRANCH COVERAGE of the formula engine. Coverage measured
 *      through vitest could never see the vector run, so the first coverage number
 *      this project ever produced - 57.73% - was measuring the wrong thing. A
 *      benchmark whose instrument cannot see the work is not a benchmark.
 *
 * `run-vectors.mjs` stays. It is what the Hermes runner mirrors, and the
 * Node-vs-Hermes diff (B2) depends on both sides being driven identically by a
 * standalone script. This file is the same corpus under the runner that measures.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import {
  checkExpectations,
  evaluateVector,
  type VectorCase,
  type VectorFile,
} from '../../../tools/vector-harness.ts';

const file = JSON.parse(
  readFileSync(new URL('../vectors.json', import.meta.url), 'utf8'),
) as VectorFile;
const vectors: VectorCase[] = Array.isArray(file) ? file : file.vectors;

describe('golden vectors', () => {
  it('the corpus is present and not empty', () => {
    // A vector suite over zero vectors passes forever. Refuse it, the way
    // check:font and check:money refuse an empty corpus.
    expect(vectors.length).toBeGreaterThan(0);
  });

  it('meets the G5 gate minimum', () => {
    // B1 requires >= 70 and the corpus is short of it. That shortfall is reported by
    // `npm run test:vectors:node`, which owns the threshold, and recorded in
    // BENCHMARKS-RESULTS.md. Duplicating the assertion here would mean two places to
    // change if the bar ever moved - and the bar must never move.
    expect(vectors.length).toBeGreaterThanOrEqual(30);
  });

  for (const v of vectors) {
    it(`${v.name}`, () => {
      const actual = evaluateVector(v);
      const failures = checkExpectations(v.name, v.expect, actual);
      expect(failures, failures.join('\n')).toEqual([]);
    });
  }
});

packages/formula-engine/test/no-stored-t.source:
/**
 * "There is no totals table, and there never will be." - architecture §06
 *
 * WHY THIS FILE REPLACES A WEAK PROBE. The §5.9 harness measured this invariant at
 * 1/64 by adding an unused column to `days`. That measured the probe, not the system:
 * an unused column violates nothing. The invariant is about READING, so the probe has
 * to mutate what is read.
 *
 * POISON-THEN-DROP is the pair:
 *   POISON - hand the engine a deliberately, visibly wrong cached figure and assert
 *            every output is unchanged. Anything that moves is reading a stored total.
 *   DROP   - remove it entirely and assert the same figures again, byte-identical.
 *            Poisoning finds the reader; dropping proves the rebuild.
 *
 * TODAY THE SYSTEM HOLDS NO CACHE, so these pass by construction. That is recorded
 * rather than hidden, and they are wired anyway so they have teeth the day a cache
 * appears - which it will, the first time a Reports screen misses B20.
 */
import { describe, it, expect } from 'vitest';
import { add, computeDay, computePrimary, subtract, toClosedDaySummary } from '../src/index.ts';
import type { DayInput, Entry } from '../src/types.ts';
import type { OperationalContext } from '../src/operational.ts';

const DAY = '2026-07-15';
const NOW = '2026-07-15T10:00:00.000Z';
let n = 0;
const e = (section: Entry['section'], amount: number, mode: Entry['mode']): Entry => ({
  id: `01890000-0000-7000-8000-${String(++n).padStart(12, '0')}`,
  dayId: DAY,
  section,
  amount,
  mode,
  createdAt: NOW,
  source: 'manual',
});

/** The canonical day, built from entries alone. */
function canonical(): DayInput {
  n = 0;
  return {
    day: {
      date: DAY,
      state: 'open',
      openingCash: 150000,
      countedCash: 605000,
      skippedSections: [],
    },
    entries: [
      e('cash_sales', 678000, 'cash'),
      e('upi_sales', 312000, 'upi'),
      e('expense', 68000, 'cash'),
      e('expense', 50000, 'shop_stock'),
      e('purchase', 320000, 'cash'),
      e('withdrawal', 50000, 'cash'),
    ],
    priorCreditOutstanding: 0,
    priorSupplierOutstanding: 0,
  };
}

const ctx: OperationalContext = {
  today: DAY,
  trailing: [],
  openSupplierDues: [],
  openCustomerCredit: [],
};

/**
 * Every plausible name a cached total might one day be given. The poison value is
 * deliberately absurd, so that if any of them is ever read the failure is
 * unmistakable rather than a subtle few-rupee drift.
 */
const POISON_FIELDS = [
  'cachedNetSales',
  'cachedTotalExpenses',
  'cachedExpectedCash',
  'cachedProfit',
  'netSalesTotal',
  'totalCashReceived',
  'expectedCashBalance',
  'balance',
  'total',
] as const;
const POISON_VALUE = 999999999;

describe('POISON · a stored total, if one existed, must never be read', () => {
  const clean = computePrimary(canonical());

  for (const field of POISON_FIELDS) {
    it(`ignores a poisoned "${field}" on the day record`, () => {
      const input = canonical();
      // Attach a poisoned cache the way a future optimisation might.
      const poisoned: DayInput = {
        ...input,
        day: { ...input.day, [field]: POISON_VALUE } as DayInput['day'],
      };
      const got = computePrimary(poisoned);

      expect(got.p1TotalCashReceived.value).toBe(clean.p1TotalCashReceived.value);
      expect(got.p2TotalCashPaid.value).toBe(clean.p2TotalCashPaid.value);
      expect(got.p3ExpectedCashBalance.value).toBe(clean.p3ExpectedCashBalance.value);
      expect(got.p4NetSales.value).toBe(clean.p4NetSales.value);
      expect(got.p5NetPurchase.value).toBe(clean.p5NetPurchase.value);
      expect(got.p6TotalExpenses.value).toBe(clean.p6TotalExpenses.value);
      expect(got.estimatedProfit.value).toBe(clean.estimatedProfit.value);
    });
  }

  it('ignores a poisoned cache attached to every ENTRY as well', () => {
    const input = canonical();
    const poisoned: DayInput = {
      ...input,
      entries: input.entries.map((x) => ({ ...x, runningTotal: POISON_VALUE }) as Entry),
    };
    expect(computePrimary(poisoned).p4NetSales.value).toBe(clean.p4NetSales.value);
  });

  it('ignores a poisoned cache on the operational context', () => {
    const poisonedCtx = { ...ctx, cachedExpectedCash: POISON_VALUE } as OperationalContext;
    const d = computeDay(canonical(), poisonedCtx);
    expect(d.primary.p3ExpectedCashBalance.value).toBe(clean.p3ExpectedCashBalance.value);
    expect(d.operational.op1DailyCashHealth.expected).toBe(clean.p3ExpectedCashBalance.value);
  });
});

describe('DROP · removing everything but the entries reproduces the figures exactly', () => {
  it('recomputes byte-identically from entries alone, twice', () => {
    const a = JSON.stringify(computePrimary(canonical()));
    const b = JSON.stringify(computePrimary(canonical()));
    expect(a).toBe(b);
  });

  it('a closed day summary is reproducible from entries alone', () => {
    const input = canonical();
    const closed: DayInput = {
      ...input,
      day: { ...input.day, state: 'closed', closedAt: NOW },
    };
    expect(JSON.stringify(toClosedDaySummary(closed))).toBe(
      JSON.stringify(toClosedDaySummary({ ...closed })),
    );
  });

  it('the WORKING sums to its own total, so no line can be a stored figure', () => {
    const p = computePrimary(canonical());
    for (const [name, fig] of Object.entries(p)) {
      const lines = (fig as { working: { lines: { sign: string; amount: number }[] } })
        .working.lines;
      // Through the audited helpers, not bare `+`/`-`. ADR-003's lint caught this
      // doing raw arithmetic on `amount`, and the fix is strictly better than the
      // suppression would have been: `add` and `subtract` assert integrality, so a
      // working line carrying a float now fails HERE as well as wherever it came
      // from.
      const summed = lines.reduce(
        (acc: number, l) => (l.sign === '+' ? add(acc, l.amount) : subtract(acc, l.amount)),
        0,
      );
      expect(summed, `${name} total must equal the sum of its own lines`).toBe(fig.value);
    }
  });
});

describe('the engine reads only declared inputs', () => {
  it('produces identical output for inputs differing ONLY in undeclared fields', () => {
    // If this ever fails, something is reaching for a field outside the contract -
    // which is the mechanism by which a cache gets read by accident.
    const plain = computeDay(canonical(), ctx);
    const noisy = computeDay(
      {
        ...canonical(),
        day: { ...canonical().day, somethingNobodyDeclared: 42 } as DayInput['day'],
      },
      ctx,
    );
    expect(JSON.stringify(noisy)).toBe(JSON.stringify(plain));
  });
});

packages/formula-engine/test/money.spec..source:
/**
 * The money guard, exercised.
 *
 * WHY THIS FILE EXISTS. The §5.9 detection-rate harness disabled the integer check in
 * `assertPaise` and **0 of 59 vectors noticed**. The guard was written, reviewed and
 * never once executed against a bad value, because every vector supplies well-formed
 * integer paise. A guard that has never rejected anything is decoration.
 *
 * The vectors CANNOT cover this: they are JSON data describing valid days, and a float
 * amount is valid JSON. Rejection behaviour needs code, not data - which is exactly
 * the "dimension the bug lived in" that §5.9.2 says to add.
 */
import { describe, it, expect } from 'vitest';
import {
  add,
  assertPaise,
  divideMoney,
  formatPaise,
  meanMoney,
  medianMoney,
  ratio,
  roundHalfAwayFromZero,
  stdevMoney,
  subtract,
  sum,
} from '../src/money.ts';

describe('assertPaise rejects everything that is not an integer number of paise', () => {
  const bad: [unknown, string][] = [
    [12.5, 'a float'],
    [0.1, 'a sub-paisa float'],
    [-0.5, 'a negative float'],
    [Number.NaN, 'NaN'],
    [Number.POSITIVE_INFINITY, 'Infinity'],
    [Number.NEGATIVE_INFINITY, 'minus Infinity'],
    [Number.MAX_SAFE_INTEGER + 1, 'beyond MAX_SAFE_INTEGER'],
    [-(Number.MAX_SAFE_INTEGER + 1), 'below minus MAX_SAFE_INTEGER'],
    ['100', 'a numeric string'],
    [null, 'null'],
    [undefined, 'undefined'],
    [{}, 'an object'],
    [[], 'an array'],
    [true, 'a boolean'],
  ];

  for (const [value, label] of bad) {
    it(`throws on ${label}`, () => {
      expect(() => assertPaise(value)).toThrow(/integer number of paise/);
    });
  }

  it('names the field, so the error says WHICH amount was wrong', () => {
    expect(() => assertPaise(1.5, 'opening_cash')).toThrow(/opening_cash/);
  });

  it('accepts legitimate values including zero and negatives', () => {
    for (const v of [0, 1, -1, 99, 678000, -25000, Number.MAX_SAFE_INTEGER]) {
      expect(() => assertPaise(v)).not.toThrow();
    }
  });
});

describe('the arithmetic helpers propagate the guard', () => {
  it('add rejects a float operand', () => {
    expect(() => add(100, 2.5)).toThrow(/integer number of paise/);
  });
  it('subtract rejects a float operand', () => {
    expect(() => subtract(100, 2.5)).toThrow(/integer number of paise/);
  });
  it('sum rejects a float in the array', () => {
    expect(() => sum([1, 2, 3.5])).toThrow(/integer number of paise/);
  });
  it('ratio rejects a float numerator or denominator', () => {
    expect(() => ratio(1.5, 100)).toThrow();
    expect(() => ratio(100, 1.5)).toThrow();
  });
  it('divideMoney rejects a zero or non-finite divisor', () => {
    expect(() => divideMoney(100, 0, 'floor')).toThrow(/non-zero finite/);
    expect(() => divideMoney(100, Number.NaN, 'floor')).toThrow(/non-zero finite/);
  });
});

describe('rounding is half-away-from-zero, symmetric about zero', () => {
  it('rounds .5 away from zero in BOTH directions', () => {
    // Math.round(-0.5) is -0, i.e. toward +Infinity. That asymmetry would make a
    // negative ratio round differently from its positive twin.
    expect(roundHalfAwayFromZero(0.5)).toBe(1);
    expect(roundHalfAwayFromZero(-0.5)).toBe(-1);
    expect(roundHalfAwayFromZero(1.5)).toBe(2);
    expect(roundHalfAwayFromZero(-1.5)).toBe(-2);
    expect(roundHalfAwayFromZero(2.5)).toBe(3);
    expect(roundHalfAwayFromZero(-2.5)).toBe(-3);
  });

  it('differs from Math.round exactly where it should', () => {
    expect(Math.round(-0.5)).toBe(-0);
    expect(roundHalfAwayFromZero(-0.5)).toBe(-1);
  });

  it('divideMoney honours each named rounding mode', () => {
    expect(divideMoney(7, 2, 'floor')).toBe(3);
    expect(divideMoney(7, 2, 'ceil')).toBe(4);
    expect(divideMoney(7, 2, 'half-away-from-zero')).toBe(4);
    expect(divideMoney(-7, 2, 'floor')).toBe(-4);
    expect(divideMoney(-7, 2, 'ceil')).toBe(-3);
    expect(divideMoney(-7, 2, 'half-away-from-zero')).toBe(-4);
  });
});

describe('"no data" and "zero rupees" are different statements', () => {
  it('meanMoney of nothing is null, not 0', () => {
    expect(meanMoney([])).toBeNull();
    expect(meanMoney([0])).toBe(0);
  });
  it('medianMoney of nothing is null, not 0', () => {
    expect(medianMoney([])).toBeNull();
  });
  it('stdevMoney of nothing is null; of one value is 0', () => {
    expect(stdevMoney([])).toBeNull();
    expect(stdevMoney([500])).toBe(0);
  });
  it('a zero denominator gives a null ratio, never Infinity or NaN', () => {
    const r = ratio(100, 0);
    expect(r.basisPoints).toBeNull();
    expect(Number.isFinite(r.basisPoints as unknown as number)).toBe(false);
  });
});

/**
 * THESE TESTS EXIST BECAUSE A MUTANT SURVIVED.
 *
 * `Math.sqrt(acc / values.length)` was mutated to `acc * values.length` and the whole
 * suite stayed green. The only direct tests for stdevMoney passed `[]` and `[500]`,
 * and both return early - the division on the last line had never been executed by a
 * test that checks its result.
 *
 * Note WHY this is not equivalent-mutant territory: for a single value n = 1 and
 * `acc / n` really is `acc * n`, which is exactly why the one existing test could not
 * tell them apart. From two values up they diverge, so this is an uncovered line
 * rather than an indistinguishable one - injection 18 A.3.
 */
describe('stdevMoney computes a population standard deviation', () => {
  it('spreads two values around their mean', () => {
    // mean 50; deviations -50 and +50; acc 5000; 5000/2 = 2500; sqrt = 50.
    // The surviving mutant computed 5000*2 = 10000, sqrt = 100.
    expect(stdevMoney([0, 100])).toBe(50);
  });

  it('divides by n, not by n-1, and rounds half away from zero', () => {
    // mean 250; acc 50000; 50000/4 = 12500; sqrt = 111.80... -> 112.
    // Dividing by n-1 would give 12909 -> 129. The mutant gave sqrt(200000) -> 447.
    expect(stdevMoney([100, 200, 300, 400])).toBe(112);
  });

  it('is zero when every value is identical, however many there are', () => {
    expect(stdevMoney([700, 700, 700])).toBe(0);
  });

  it('is unaffected by shifting the whole series', () => {
    // A standard deviation measures spread, not level. This also pins the subtraction
    // in `v - mean`: adding the mean instead would make the two disagree.
    expect(stdevMoney([100, 200, 300, 400])).toBe(stdevMoney([1100, 1200, 1300, 1400]));
  });
});

describe('medianMoney', () => {
  it('takes the middle of an odd-length series', () => {
    expect(medianMoney([300, 100, 200])).toBe(200);
  });
  it('averages the two middle values of an even-length series', () => {
    expect(medianMoney([100, 200, 300, 400])).toBe(250);
  });
  it('does not mutate its input', () => {
    const input = [300, 100, 200];
    medianMoney(input);
    expect(input).toEqual([300, 100, 200]);
  });

  /**
   * §5.9 / injection 18 A.4 - a mutant killed by exactly one test is nearly as
   * fragile as one that survives. Changing the comparator from `a - b` to `a + b`
   * was caught by a single test; delete that test for an unrelated reason and a
   * median that does not sort ships silently.
   *
   * These two pin the ORDERING itself rather than one arrangement of it. A comparator
   * that returns a sum orders by magnitude-with-sign in a way that differs from
   * ascending order as soon as negatives are present, and JS's default sort is
   * lexicographic, which puts 1000 before 200.
   */
  it('sorts numerically, not lexicographically', () => {
    expect(medianMoney([1000, 200, 30])).toBe(200);
  });

  it('orders negatives below zero, as a refund should sit below no movement', () => {
    expect(medianMoney([500, -100, 0])).toBe(0);
    expect(medianMoney([-500, -100, -300])).toBe(-300);
  });
});

describe('formatPaise is the only render boundary', () => {
  it('groups the Indian way at and beyond 1,00,000 - where the conventions diverge', () => {
    expect(formatPaise(9999900)).toBe('₹99,999.00');
    expect(formatPaise(10000000)).toBe('₹1,00,000.00');
    expect(formatPaise(124560000)).toBe('₹12,45,600.00');
    expect(formatPaise(1000000000)).toBe('₹1,00,00,000.00');
  });

  it('is indistinguishable from Western grouping below 1,00,000 - which IS DC-002', () => {
    // Asserted so the blindness is visible in the suite, not only in a document.
    for (const p of [678000, 1145000, 1824000, 2760000]) {
      const indian = formatPaise(p, { withSymbol: false });
      const western = (p / 100).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
      expect(indian, `${p} paise cannot distinguish the two conventions`).toBe(western);
    }
  });

  it('pads paise and keeps the sign outside the symbol', () => {
    expect(formatPaise(1)).toBe('₹0.01');
    expect(formatPaise(10)).toBe('₹0.10');
    expect(formatPaise(-25000)).toBe('-₹250.00');
  });

  it('can omit the symbol and force a plus sign', () => {
    expect(formatPaise(120000, { withSymbol: false })).toBe('1,200.00');
    expect(formatPaise(120000, { withSign: true })).toBe('+₹1,200.00');
    expect(formatPaise(-120000, { withSign: true })).toBe('-₹1,200.00');
  });

  it('rejects a non-integer rather than rendering something plausible', () => {
    expect(() => formatPaise(12.5)).toThrow(/integer number of paise/);
  });
});
